import csv, json, math
import numpy as np

BASE = '/home/ubuntu/.agent-ml-research-idea_gen_0514_5/projects/causal_style_decomp_judge'

def load_csv(path):
    with open(path, encoding='utf-8-sig') as f:
        return list(csv.DictReader(f))

a1 = load_csv(f'{BASE}/docs/causal-1.csv')
a2 = load_csv(f'{BASE}/docs/causal-2.csv')

def norm(v):
    if v is None: return ''
    return v.strip().lower()

def wilson_ci(p, n, z=1.96):
    if n == 0: return (0, 0)
    denom = 1 + z**2/n
    center = (p + z**2/(2*n)) / denom
    spread = z * math.sqrt((p*(1-p) + z**2/(4*n)) / n) / denom
    return (max(0, center - spread), min(1, center + spread))

# ===== 1. NLI Gate Validation =====
results = {"gate_validation": {}, "agreement": {}, "disagreements": [], "comparison_with_50pair": {}}

for label, data in [("annotator_1", a1), ("annotator_2", a2)]:
    nli_pass = [r for r in data if norm(r['nli_pass']) == 'true']
    nli_fail = [r for r in data if norm(r['nli_pass']) != 'true']

    # Gate precision: NLI-pass → preserves_meaning=Yes
    prec_n = len(nli_pass)
    prec_yes = sum(1 for r in nli_pass if norm(r['preserves_meaning']) == 'yes')
    prec = prec_yes / prec_n if prec_n > 0 else 0

    # Gate recall (false rejection): NLI-fail → preserves_meaning=Yes (gate incorrectly rejected)
    recall_n = len(nli_fail)
    recall_yes = sum(1 for r in nli_fail if norm(r['preserves_meaning']) == 'yes')
    false_reject_rate = recall_yes / recall_n if recall_n > 0 else 0

    # Style change detection in NLI-pass
    style_yes = sum(1 for r in nli_pass if norm(r['style_change_detected']) == 'yes')
    style_rate = style_yes / prec_n if prec_n > 0 else 0

    results["gate_validation"][label] = {
        "precision": {"value": round(prec, 4), "n": prec_n, "yes": prec_yes, "ci_95": [round(x,4) for x in wilson_ci(prec, prec_n)]},
        "false_rejection_rate": {"value": round(false_reject_rate, 4), "n": recall_n, "yes": recall_yes, "ci_95": [round(x,4) for x in wilson_ci(false_reject_rate, recall_n)]},
        "style_change_rate_nli_pass": {"value": round(style_rate, 4), "n": prec_n, "yes": style_yes, "ci_95": [round(x,4) for x in wilson_ci(style_rate, prec_n)]}
    }

# ===== 2. Inter-annotator Agreement =====
def cohens_kappa(a_labels, b_labels, categories=None):
    if categories is None:
        categories = sorted(set(a_labels) | set(b_labels))
    n = len(a_labels)
    # Confusion matrix
    matrix = {}
    for c1 in categories:
        for c2 in categories:
            matrix[(c1,c2)] = 0
    for a, b in zip(a_labels, b_labels):
        matrix[(a,b)] += 1

    po = sum(matrix[(c,c)] for c in categories) / n
    pe = sum((sum(matrix[(c,c2)] for c2 in categories) / n) * (sum(matrix[(c2,c)] for c2 in categories) / n) for c in categories)

    if pe == 1: return 1.0
    return (po - pe) / (1 - pe)

def gwets_ac1(a_labels, b_labels, categories=None):
    if categories is None:
        categories = sorted(set(a_labels) | set(b_labels))
    n = len(a_labels)

    po = sum(1 for a, b in zip(a_labels, b_labels) if a == b) / n

    # Marginal probabilities
    pks = []
    for c in categories:
        pk = (sum(1 for x in a_labels if x == c) + sum(1 for x in b_labels if x == c)) / (2 * n)
        pks.append(pk)

    pe = sum(pk * (1 - pk) for pk in pks) / (len(categories) - 1) if len(categories) > 1 else 0

    if pe == 1: return 1.0
    return (po - pe) / (1 - pe)

# preserves_meaning
pm_a1 = [norm(r['preserves_meaning']) for r in a1]
pm_a2 = [norm(r['preserves_meaning']) for r in a2]

kappa_pm_all = cohens_kappa(pm_a1, pm_a2)

# By NLI subset
nli_pass_idx = [i for i in range(100) if norm(a1[i]['nli_pass']) == 'true']
nli_fail_idx = [i for i in range(100) if norm(a1[i]['nli_pass']) != 'true']

pm_a1_pass = [pm_a1[i] for i in nli_pass_idx]
pm_a2_pass = [pm_a2[i] for i in nli_pass_idx]
pm_a1_fail = [pm_a1[i] for i in nli_fail_idx]
pm_a2_fail = [pm_a2[i] for i in nli_fail_idx]

# style_change_detected
sc_a1 = [norm(r['style_change_detected']) for r in a1]
sc_a2 = [norm(r['style_change_detected']) for r in a2]
kappa_sc_all = cohens_kappa(sc_a1, sc_a2)

# Gwet's AC1
ac1_pm_all = gwets_ac1(pm_a1, pm_a2)
ac1_sc_all = gwets_ac1(sc_a1, sc_a2)

# Kappa for subsets
try:
    kappa_pm_pass = cohens_kappa(pm_a1_pass, pm_a2_pass)
except:
    kappa_pm_pass = None
try:
    kappa_pm_fail = cohens_kappa(pm_a1_fail, pm_a2_fail)
except:
    kappa_pm_fail = None

results["agreement"] = {
    "preserves_meaning": {
        "kappa_all": round(kappa_pm_all, 4),
        "kappa_nli_pass": round(kappa_pm_pass, 4) if kappa_pm_pass is not None else "N/A",
        "kappa_nli_fail": round(kappa_pm_fail, 4) if kappa_pm_fail is not None else "N/A",
        "ac1_all": round(ac1_pm_all, 4),
        "agreement_rate": round(sum(1 for a,b in zip(pm_a1, pm_a2) if a == b) / 100, 4)
    },
    "style_change_detected": {
        "kappa_all": round(kappa_sc_all, 4),
        "ac1_all": round(ac1_sc_all, 4),
        "agreement_rate": round(sum(1 for a,b in zip(sc_a1, sc_a2) if a == b) / 100, 4)
    }
}

# ===== 3. Disagreement Analysis =====
for i in range(100):
    if pm_a1[i] != pm_a2[i]:
        results["disagreements"].append({
            "sample_id": a1[i]['sample_id'],
            "axis": a1[i]['axis'],
            "source_id": a1[i]['source_id'],
            "nli_pass": norm(a1[i]['nli_pass']),
            "nli_score": a1[i]['nli_score'],
            "a1_preserves_meaning": pm_a1[i],
            "a2_preserves_meaning": pm_a2[i],
            "a1_notes": a1[i].get('notes', ''),
            "a2_notes": a2[i].get('notes', '')
        })

# Disagreement by axis
disagree_axis = {}
for d in results["disagreements"]:
    ax = d["axis"]
    disagree_axis[ax] = disagree_axis.get(ax, 0) + 1

results["disagreement_summary"] = {
    "total": len(results["disagreements"]),
    "by_axis": disagree_axis,
    "by_nli_pass": {
        "nli_pass": sum(1 for d in results["disagreements"] if d["nli_pass"] == "true"),
        "nli_fail": sum(1 for d in results["disagreements"] if d["nli_pass"] != "true")
    }
}

# NLI-pass pairs where any annotator said No
nli_pass_flagged = []
for i in nli_pass_idx:
    if pm_a1[i] == 'no' or pm_a2[i] == 'no':
        nli_pass_flagged.append({
            "sample_id": a1[i]['sample_id'],
            "axis": a1[i]['axis'],
            "source_id": a1[i]['source_id'],
            "nli_score": a1[i]['nli_score'],
            "a1": pm_a1[i],
            "a2": pm_a2[i]
        })

results["sensitivity_flagged_pairs"] = nli_pass_flagged

# ===== 5. Comparison with 50-pair =====
results["comparison_with_50pair"] = {
    "previous_50": {"a1_precision": 1.00, "a2_precision": 0.84, "kappa_pm": 0.44, "ac1_pm": 0.65},
    "current_100": {
        "a1_precision": results["gate_validation"]["annotator_1"]["precision"]["value"],
        "a2_precision": results["gate_validation"]["annotator_2"]["precision"]["value"],
        "kappa_pm": results["agreement"]["preserves_meaning"]["kappa_all"],
        "ac1_pm": results["agreement"]["preserves_meaning"]["ac1_all"]
    }
}

# Save
import os
os.makedirs(f'{BASE}/artifacts/r16_analysis', exist_ok=True)
with open(f'{BASE}/artifacts/r16_analysis/human_annotation_analysis.json', 'w') as f:
    json.dump(results, f, indent=2, ensure_ascii=False)

print(json.dumps(results, indent=2, ensure_ascii=False))
